-- Proposed Neon/PostgreSQL schema for the next phase; not wired to the V1 preview.
-- Server-side authentication and per-project authorization are required before exposure.
create extension if not exists pgcrypto;
create table app_users (id uuid primary key default gen_random_uuid(), auth_subject text unique not null, email text, created_at timestamptz not null default now());
create table projects (id uuid primary key default gen_random_uuid(), owner_id uuid not null references app_users(id), name text not null, description text, budget numeric(14,2) not null default 0 check(budget>=0), currency char(3) not null default 'BRL', created_at timestamptz not null default now());
create table project_members (project_id uuid references projects(id) on delete cascade, user_id uuid references app_users(id) on delete cascade, role text not null check(role in ('owner','editor','viewer')), primary key(project_id,user_id));
create table rooms (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, name text not null, unique(project_id,name), unique(id,project_id));
create table categories (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, name text not null, unique(project_id,name), unique(id,project_id));
create table items (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, room_id uuid not null, category_id uuid not null, parent_id uuid, name text not null, quantity integer not null default 1 check(quantity>0), unit_budget numeric(14,2) not null default 0 check(unit_budget>=0), status text not null default 'Planejado' check(status in ('Planejado','Pesquisando','Comprado','Recebido')), priority text not null default 'Média' check(priority in ('Alta','Média','Baixa')), notes text, reference_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(id,project_id), foreign key(room_id,project_id) references rooms(id,project_id), foreign key(category_id,project_id) references categories(id,project_id), foreign key(parent_id,project_id) references items(id,project_id) on delete cascade, check(parent_id is distinct from id));
create table purchases (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, item_id uuid not null unique, paid_total numeric(14,2) not null check(paid_total>=0), payment_method text not null, installments integer not null default 1 check(installments between 1 and 120), purchased_on date not null, store text, product_url text, foreign key(item_id,project_id) references items(id,project_id) on delete cascade);
create table offers (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, item_id uuid not null, store text not null, model text, product_url text, source text not null check(source in ('import','web','manual')), created_at timestamptz not null default now(), unique(id,project_id), foreign key(item_id,project_id) references items(id,project_id) on delete cascade);
create table price_snapshots (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, offer_id uuid not null, price numeric(14,2) not null check(price>0), shipping numeric(14,2) check(shipping>=0), observed_on date not null, observed_at timestamptz, rating numeric(3,2) check(rating between 0 and 5), review_count integer check(review_count>=0), source_label text, notes text, image_url text, currency char(3) not null default 'BRL', source_url text, foreign key(offer_id,project_id) references offers(id,project_id) on delete cascade);
create table import_templates (id uuid primary key default gen_random_uuid(), owner_id uuid not null references app_users(id), name text not null, columns jsonb not null, created_at timestamptz not null default now());
create index items_project_room_idx on items(project_id,room_id);
create index items_parent_idx on items(parent_id);
create index price_history_idx on price_snapshots(offer_id,observed_at desc);
-- Ancestor cycle checks, same-room/category inheritance, status/purchase consistency,
-- authorization, and import transactions must be implemented in the server phase.
